int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    final byte[] data = schema.writeTo(buffer, message);
    final int size = data.length;
    final int len = VarInt.sizeOfSInt32(size);
    if (len > buffer.buffer.length - buffer.offset) Bytes.copyTo(new byte[len], 0, buffer.buffer, buffer.offset, len);
    VarInt.writeSInt32(size, buffer);
    out.write(buffer.buffer, 0, buffer.offset + len);
    out.write(data);
    return size;
}

int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    byte[] data = schema.toByteArray(message, buffer);
    int size = data.length;
    out.write((size & 0xFF));
    out.write((size & 0xFF00) >>> 8);
    out.write((size & 0xFF0000) >>> 16);
    out.write((size & 0xFF000000) >>> 24);
    out.write(data);
    return size;
}

