            pathSegments.add(new PathSegmentImpl(decode ? decodeURIComponent(segment) : segment));
            segmentBuilder.setLength(0);
        } else {
            segmentBuilder.append(c);
        }
    }
    // Add the last segment
    String lastSegment = segmentBuilder.toString();
    if (!lastSegment.isEmpty()) {
        pathSegments.add(new PathSegmentImpl(decode ? decodeURIComponent(lastSegment) : lastSegment));
    }
    return pathSegments;
