    if (number <= 1) {
        return false;
    }
    if (number <= 3) {
        return true;
    }
    if (number % 2 == 0 || number % 3 == 0) {
        return false;
    }
    for (int i = 5; i * i <= number; i += 6) {
        if (number % i == 0 || number % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

int findClosePrime(int desiredCapacity) {
    int lowerBound = (int) (desiredCapacity * 0.89);
    int upperBound = desiredCapacity;
    for (int i = upperBound; i >= lowerBound; i--) {
        if (isPrime(i)) {
            return i;
        }
    }
    return desiredCapacity; // fallback, should not reach here if logic is correct
}

