GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    List<E> edgeList = new ArrayList<>(tour);
    if (edgeList.isEmpty()) {
        return null; // or throw an exception if an empty path is not allowed
    }

    List<V> vertexList = new ArrayList<>();
    for (E edge : edgeList) {
        V sourceVertex = graph.getEdgeSource(edge);
        V targetVertex = graph.getEdgeTarget(edge);

        if (vertexList.isEmpty() || !vertexList.get(vertexList.size() - 1).equals(sourceVertex)) {
            throw new IllegalArgumentException("Edges are not forming a valid path");
        }

        vertexList.add(targetVertex);
    }

    return new SimpleGraphPath<>(graph, vertexList.get(0), vertexList.get(vertexList.size() - 1), vertexList, edgeList);
}

GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }

    List<E> edgeList = new ArrayList<>(tour);
    if (edgeList.isEmpty()) {
        return GraphWalk.singleton(graph.getVertexFactory().createVertex());
    }

    V startVertex = null;
    Map<V, V> vertexMap = new HashMap<>();
    Set<V> visitedVertices = new HashSet<>();

    for (E edge : edgeList) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        if (!visitedVertices.contains(source)) {
            startVertex = source;
            break;
        }
        visitedVertices.add(source);
        visitedVertices.add(target);
    }

    if (startVertex == null) {
        throw new IllegalStateException("Could not determine a valid start vertex for the tour");
    }

    List<V> vertexList = new ArrayList<>();
    V currentVertex = startVertex;

    while (edgeList.size() > 0) {
        vertexList.add(currentVertex);

        E nextEdge = findEdge(currentVertex, edgeList);
        if (nextEdge == null) {
            throw new IllegalStateException("Tour is invalid, cannot find next edge for vertex: " + currentVertex);
        }

        currentVertex = graph.getEdgeTarget(nextEdge).equals(currentVertex) ? graph.getEdgeSource(nextEdge) : graph.getEdgeTarget(nextEdge);
        edgeList.remove(nextEdge);
    }

    vertexList.add(currentVertex); // Add the last vertex to close the cycle

    return new GraphPathImpl<>(graph, startVertex, currentVertex, vertexList, edgeList, 0);
}

GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    if (tour.isEmpty()) {
        return new SimpleGraphPath<>(graph, null, null, 0.0);
    }

    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = graph.getEdgeSource(edgeList.get(0));
    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);

    for (E edge : edgeList) {
        V targetVertex = graph.getEdgeTarget(edge);
        vertexList.add(targetVertex);
        startVertex = targetVertex;
    }

    return new SimpleGraphPath<>(graph, vertexList.get(0), vertexList.get(vertexList.size() - 1), edgeList);
}

