GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }

    List<E> edgeList = new ArrayList<>(tour);
    if (edgeList.isEmpty()) {
        throw new IllegalArgumentException("Tour cannot be empty");
    }

    V startVertex = null;
    Map<E, V> edgeTargetMap = new HashMap<>();
    Map<V, Integer> vertexDegreeMap = new HashMap<>();

    // Populate edgeTargetMap and vertexDegreeMap
    for (E edge : edgeList) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        edgeTargetMap.put(edge, target);
        vertexDegreeMap.put(source, vertexDegreeMap.getOrDefault(source, 0) + 1);
        vertexDegreeMap.put(target, vertexDegreeMap.getOrDefault(target, 0) + 1);
    }

    // Find the start vertex (should have odd degree, unless it's a loop)
    for (Map.Entry<V, Integer> entry : vertexDegreeMap.entrySet()) {
        if (entry.getValue() % 2 != 0) {
            startVertex = entry.getKey();
            break;
        }
    }

    // If no start vertex found, pick any vertex
    if (startVertex == null) {
        startVertex = graph.getEdgeSource(edgeList.get(0));
    }

    List<E> pathEdges = new ArrayList<>();
    Set<E> visitedEdges = new HashSet<>();

    // Construct the path
    V currentVertex = startVertex;
    while (!visitedEdges.containsAll(edgeList)) {
        E nextEdge = null;
        for (E edge : edgeList) {
            if (!visitedEdges.contains(edge) && graph.getEdgeSource(edge).equals(currentVertex)) {
                nextEdge = edge;
                break;
            }
        }
        if (nextEdge != null) {
            pathEdges.add(nextEdge);
            visitedEdges.add(nextEdge);
            currentVertex = edgeTargetMap.get(nextEdge);
        }
    }

    return new GraphPathImpl<>(graph, startVertex, currentVertex, pathEdges);
}

