    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("Name and descriptor must not be null");
    }
    int hashCode = name.hashCode() * 0x7F + descriptor.hashCode() * 0x1F + 0x7AFE;
    Symbol existing = getSymbol(hashCode, name, descriptor);
    if (existing != null) {
        return existing.index;
    }
    return addConstantUtf8AndSymbol(7, name, descriptor, hashCode);
}

int addConstantNameAndType(final String name, final String descriptor) {
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("Name and descriptor must not be null");
    }
    for (int i = 1; i < constantPool.size(); i++) {
        ConstantNameAndTypeInfo existing = constantPool.get(i);
        if (existing != null && existing.name.equals(name) && existing.descriptor.equals(descriptor)) {
            return i;
        }
    }
    ConstantNameAndTypeInfo newNameAndTypeInfo = new ConstantNameAndTypeInfo(name, descriptor);
    constantPool.add(newNameAndTypeInfo);
    return constantPool.size() - 1;
}

int addConstantNameAndType(final String name, final String descriptor) {
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("Name and descriptor cannot be null");
    }
    for (int i = 1; i < constantPool.size(); i++) {
        Object[] cpInfo = constantPool.get(i);
        if (cpInfo[0] == CONSTANT_NameAndType && name.equals(cpInfo[1]) && descriptor.equals(cpInfo[2])) {
            return i;
        }
    }
    constantPool.add(new Object[]{CONSTANT_NameAndType, name, descriptor});
    return constantPool.size() - 1;
}

int addConstantNameAndType(final String name, final String descriptor) {
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("Name and descriptor must not be null");
    }
    for (int i = 1; i < constantPool.size(); i++) {
        ConstantPoolEntry entry = constantPool.get(i);
        if (entry instanceof ConstantNameAndTypeEntry) {
            ConstantNameAndTypeEntry nameAndTypeEntry = (ConstantNameAndTypeEntry) entry;
            if (nameAndTypeEntry.getName().equals(name) && nameAndTypeEntry.getDescriptor().equals(descriptor)) {
                return i;
            }
        }
    }
    ConstantNameAndTypeEntry newEntry = new ConstantNameAndTypeEntry(name, descriptor);
    constantPool.add(newEntry);
    return constantPool.size() - 1;
}

int addConstantNameAndType(final String name, final String descriptor) {
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("Name and descriptor cannot be null");
    }
    for (int i = 1; i < constantPool.size(); i++) {
        Symbol existingSymbol = (Symbol) constantPool.get(i);
        if (existingSymbol.tag == Symbol.CONSTANT_NameAndType_TAG &&
            existingSymbol.name.equals(name) &&
            existingSymbol.descriptor.equals(descriptor)) {
            return existingSymbol.index;
        }
    }
    Symbol newSymbol = new Symbol(Symbol.CONSTANT_NameAndType_TAG, name, descriptor);
    newSymbol.index = constantPool.size();
    constantPool.add(newSymbol);
    return newSymbol.index;
}

private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    // Assuming DOT escape sequence is '\.' to be replaced with '.'
    return input.replace("\\.", ".");
}

private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder output = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char currentChar = input.charAt(i);
        if (currentChar == '\\') {
            if (i + 1 < input.length()) {
                char nextChar = input.charAt(++i);
                output.append(nextChar);
            }
        } else {
            output.append(currentChar);
        }
    }
    return output.toString();
}

private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder output = new StringBuilder();
    boolean escapeNext = false;
    for (char c : input.toCharArray()) {
        if (escapeNext) {
            output.append(c);
            escapeNext = false;
        } else if (c == '\\') {
            escapeNext = true;
        } else {
            output.append(c);
        }
    }
    return output.toString();
}

private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder output = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < input.length()) {
            char nextChar = input.charAt(i + 1);
            if (nextChar == '.' || nextChar == '\\') {
                output.append(nextChar);
                i++; // Skip the next character as it's already processed
            } else {
                output.append(c); // If it's not a valid escape, keep the backslash
            }
        } else {
            output.append(c);
        }
    }
    return output.toString();
}

private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder output = new StringBuilder();
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            i++; // skip the escape character
            if (i < input.length()) {
                c = input.charAt(i);
                output.append(c); // append the character following the escape character
            }
        } else {
            output.append(c);
        }
    }
    return output.toString();
}

