private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null || minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    Set<Integer> minLabelBucket = bucketsByLabel.get(minLabel);
    if (minLabelBucket == null) {
        return; // No vertices to move
    }

    Set<Integer> zeroLabelBucket = bucketsByLabel.get(0);
    if (zeroLabelBucket == null) {
        zeroLabelBucket = new HashSet<>();
        bucketsByLabel.set(0, zeroLabelBucket);
    }

    for (Integer vertex : minLabelBucket) {
        if (vertex >= 0 && vertex < labels.size()) {
            zeroLabelBucket.add(vertex);
            labels.set(vertex, 0);
        }
    }

    minLabelBucket.clear();
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null || minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    Set<Integer> sourceBucket = bucketsByLabel.get(minLabel);
    Set<Integer> targetBucket = bucketsByLabel.get(0);

    if (sourceBucket == null) {
        throw new IllegalArgumentException("Bucket with label " + minLabel + " is null");
    }

    for (Integer vertex : sourceBucket) {
        if (vertex < 0 || vertex >= labels.size()) {
            throw new IndexOutOfBoundsException("Vertex index " + vertex + " is out of bounds for labels list");
        }
        labels.set(vertex, 0);
        targetBucket.add(vertex);
    }

    sourceBucket.clear();
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null || minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("Invalid input parameters");
    }
    Set<Integer> minLabelBucket = bucketsByLabel.get(minLabel);
    if (minLabelBucket == null) {
        return; // No vertices in this bucket to move
    }
    Set<Integer> zeroLabelBucket = bucketsByLabel.get(0);
    if (zeroLabelBucket == null) {
        bucketsByLabel.set(0, new HashSet<>(minLabelBucket));
    } else {
        zeroLabelBucket.addAll(minLabelBucket);
